const cardButtons=document.querySelectorAll('#card-choices button'),card=document.querySelector('#card-preview'),cardText=document.querySelector('#card-text'),preview=document.querySelector('#preview-text');
cardButtons.forEach(button=>button.addEventListener('click',()=>{cardButtons.forEach(item=>item.classList.remove('selected'));button.classList.add('selected');card.className='card-preview card-'+button.dataset.card}));
cardText.addEventListener('input',()=>preview.textContent=cardText.value||'メッセージを入力してください');
const occasionResult=document.querySelector('#occasion-result'),formOccasion=document.querySelector('#form-occasion');document.querySelectorAll('[data-occasion]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-occasion]').forEach(item=>item.classList.remove('active'));button.classList.add('active');occasionResult.textContent=button.dataset.occasion;[...formOccasion.options].some(option=>option.text===button.dataset.occasion)&&(formOccasion.value=button.dataset.occasion);updateSummary()}));
const fields=['form-occasion','budget','date','delivery','request'];const summary=document.querySelector('#summary');function updateSummary(){const values=Object.fromEntries(fields.map(id=>[id,document.querySelector('#'+id).value]));const cardName=document.querySelector('#card-choices .selected').textContent;summary.textContent='【elm・balloon ご相談メモ】\\nご用途：'+values['form-occasion']+'\\nご予算：'+(values.budget||'未定')+'\\nご希望日：'+(values.date||'未定')+'\\nお渡し方法：'+values.delivery+'\\nメッセージカード：'+cardName+'\\nカード文面：'+(cardText.value||'なし')+'\\nご希望：'+(values.request||'なし')};fields.forEach(id=>document.querySelector('#'+id).addEventListener('input',updateSummary));cardText.addEventListener('input',updateSummary);updateSummary();
document.querySelector('#copy-summary').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summary.textContent);const button=document.querySelector('#copy-summary');button.textContent='コピーしました！';setTimeout(()=>button.textContent='相談メモをコピー',1600)}catch{alert('コピーできませんでした。表示されたメモを長押ししてコピーしてください。')}});
